// spec: specs/location-map.md (раздел 5.1)
// seed: tests/seed.reg1.geo.spec.ts
// ВНИМАНИЕ (расхождение с планом, 19.11.2026): в живом приложении у reg1 (reg1-r12.json) тумблер «מיקום» на /settings ВКЛЮЧЁН
// (на /map пилюля «שיתוף מיקום פעיל»), поэтому предусловие плана («шаринг выключен — исходное состояние») не выполнено.
// Тест написан по плану, а состояние «выкл.» по живой странице не сверено; при включённом шаринге он честно пропускается (test.skip, «предусловие»).
// Тумблеры тест не трогает. Вкладки карты на живой странице: «עכשיו» и «היו כאן».
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/reg1-r12.json'),
  viewport: { width: 390, height: 844 },
  hasTouch: true,
  colorScheme: 'dark',
  geolocation: { latitude: 32.07, longitude: 34.79, accuracy: 10 },
  permissions: ['geolocation'],
});

test.describe('Раунд 13: приватность (#b2f39b)', () => {
  test('Шаринг и «היו כאן» выкл.: нет POST /rpc/record_location @iphone @prod-safe', async ({ page }) => {
    // 1. /settings: тумблеры «מיקום» и «היו כאן» должны быть выключены, иначе test.skip
    await page.goto('/settings');
    const locationSwitch = page.getByRole('switch', { name: 'מיקום', exact: true });
    const wereHereSwitch = page.getByRole('switch', { name: 'היו כאן', exact: true });
    await expect(locationSwitch).toBeVisible();
    await expect(wereHereSwitch).toBeVisible();
    const locationOn = (await locationSwitch.getAttribute('aria-checked')) === 'true';
    const wereHereOn = (await wereHereSwitch.getAttribute('aria-checked')) === 'true';
    test.skip(locationOn || wereHereOn, 'предусловие: тумблеры «מיקום» и «היו כאן» должны быть выключены (тест их не меняет)');

    // 2. Подписаться на запросы record_location
    const recordLocation: string[] = [];
    page.on('request', (req) => {
      if (req.method() === 'POST' && req.url().includes('/rpc/record_location')) recordLocation.push(req.url());
    });

    // 3. /map → «שיתוף מיקום כבוי»; трижды переключить вкладки; перезагрузить
    await page.goto('/map');
    await expect(page.getByText('שיתוף מיקום כבוי')).toBeVisible();

    const nowTab = page.getByRole('tab', { name: 'עכשיו', exact: true });
    const wereHereTab = page.getByRole('tab', { name: 'היו כאן', exact: true });
    for (let i = 0; i < 3; i++) {
      await wereHereTab.click();
      await expect(wereHereTab).toHaveAttribute('aria-selected', 'true');
      await nowTab.click();
      await expect(nowTab).toHaveAttribute('aria-selected', 'true');
    }

    await page.reload();
    await expect(page.getByText('שיתוף מיקום כבוי')).toBeVisible();
    await expect(page.getByText('שיתוף מיקום פעיל')).toBeHidden();

    // Ноль запросов за весь сценарий (после проверки видимости состояния)
    expect(recordLocation).toHaveLength(0);
  });
});
